@Test
func aClipboardsMarkIsTheStrictestOfItsTypes() {
  #expect(Clipboard.mark(of: ["public.utf8-plain-text"]) == 0)
  #expect(Clipboard.mark(of: ["public.utf8-plain-text", "org.nspasteboard.ConcealedType"]) == 1)
  #expect(Clipboard.mark(of: ["com.agilebits.onepassword"]) == 1)
  #expect(Clipboard.mark(of: ["de.petermaurer.TransientPasteboardType"]) == 2)
  #expect(Clipboard.mark(of: ["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType"]) == 2)
  #expect(Clipboard.mark(of: ["org.nspasteboard.AutoGeneratedType", "org.nspasteboard.ConcealedType"]) == 1)
  #expect(Clipboard.mark(of: ["com.typeit4me.clipping"]) == 3)
  #expect(Clipboard.mark(of: ["Pasteboard generator type"]) == 3)
}

@Test
func aMarkIsWrittenAsItsOwnType() {
  #expect(Clipboard.type(of: 0) == nil)
  #expect(Clipboard.type(of: 1) == "org.nspasteboard.ConcealedType")
  #expect(Clipboard.type(of: 2) == "org.nspasteboard.TransientType")
  #expect(Clipboard.type(of: 3) == "org.nspasteboard.AutoGeneratedType")
}

